import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;import com.sun.source.tree.*;import com.sun.source.util.*;
public class Scan {public static void main(String[]a)throws Exception{
 JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager fm=c.getStandardFileManager(d,null,null);JavacTask t=(JavacTask)c.getTask(null,fm,d,Arrays.asList("-proc:none","-source","8","-classpath",new String(Files.readAllBytes(Paths.get(a[1]))).trim(),"-Xmaxerrs","100000"),null,fm.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(a[0]))));Trees tr=Trees.instance(t);SourcePositions p=tr.getSourcePositions();List<CompilationUnitTree>us=new ArrayList<>();for(CompilationUnitTree u:t.parse())us.add(u);t.analyze();for(CompilationUnitTree u:us)new TreePathScanner<Void,Void>(){public Void visitMemberSelect(MemberSelectTree n,Void x){if(n.getIdentifier().contentEquals("stackSize")){Element e=tr.getElement(getCurrentPath());TypeMirror r=tr.getTypeMirror(new TreePath(getCurrentPath(),n.getExpression()));Tree parent=getCurrentPath().getParentPath().getLeaf();String k="READ";if(parent instanceof AssignmentTree&&((AssignmentTree)parent).getVariable()==n)k="WRITE";if(parent instanceof CompoundAssignmentTree&&((CompoundAssignmentTree)parent).getVariable()==n)k="COMPOUND";if(parent instanceof UnaryTree&&parent.getKind().name().matches(".*(INCREMENT|DECREMENT)"))k="UNARY";System.out.println(u.getSourceFile().getName()+"\t"+u.getLineMap().getLineNumber(p.getStartPosition(u,n))+"\t"+k+"\t"+(e==null?"?":e.getEnclosingElement())+"\t"+r+"\t"+n.toString().replace('\n',' '));}return super.visitMemberSelect(n,x);}}.scan(u,null);System.err.println("analysis errors="+d.getDiagnostics().stream().filter(q->q.getKind()==Diagnostic.Kind.ERROR).count());}}
